const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const antakyaCenter = ee.Geometry.Point([36.1678, 36.2081]); // Approximate center of Antakya
  const hatayAirport = ee.Geometry.Point([36.2840, 36.3190]); // Hatay Airport coordinates
  const roiRadius = 500; // 500 meters buffer for the regions of interest
  const antakyaROI = antakyaCenter.buffer(roiRadius);
  const airportROI = hatayAirport.buffer(roiRadius);

  const date = '2023-02-14';
  const endDate = '2023-02-15'; // Filter for a single day

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('NOAA/VIIRS/DNB/DNB_VCMCFG_v1')
    .filterDate(date, endDate)
    .select(['DNB_BRDF_Nadir', 'VCM_Mask']);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No VIIRS DNB images found for February 14, 2023.");
    console.log("C1");
    return;
  }

  // Get the single image for the day
  const image = collection.first();

  // 3. Processing - Cloud masking and radiance calculation
  // VCM_Mask value of 0 indicates high quality, cloud-free data.
  const maskedImage = image.updateMask(image.select('VCM_Mask').eq(0));
  const radianceBand = maskedImage.select('DNB_BRDF_Nadir');

  const scale = 750; // VIIRS DNB pixel resolution is ~750m at nadir

  // Function to get mean radiance and pixel count for an ROI
  const analyzeRegion = async (roi, name) => {
    const stats = await radianceBand.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const meanRadiance = stats ? stats['DNB_BRDF_Nadir'] : null;
    const pixelCount = stats ? stats['DNB_BRDF_Nadir_count'] : 0;

    return { name, meanRadiance, pixelCount };
  };

  // Analyze both regions
  const antakyaStats = await analyzeRegion(antakyaROI, 'Antakya');
  const airportStats = await analyzeRegion(airportROI, 'Hatay Airport');

  // Check for C2 (No Valid Pixels)
  if (antakyaStats.pixelCount === 0) {
    console.log(`Antakya: No valid pixels after masking (Count: ${antakyaStats.pixelCount}).`);
    console.log("C2");
    return;
  }
  if (airportStats.pixelCount === 0) {
    console.log(`Hatay Airport: No valid pixels after masking (Count: ${airportStats.pixelCount}).`);
    console.log("C2");
    return;
  }

  // Check for C3 (Calculation Failure - None, NaN, etc.)
  if (antakyaStats.meanRadiance === null || isNaN(antakyaStats.meanRadiance)) {
    console.log(`Antakya: Calculation failed (Mean Radiance: ${antakyaStats.meanRadiance}).`);
    console.log("C3");
    return;
  }
  if (airportStats.meanRadiance === null || isNaN(airportStats.meanRadiance)) {
    console.log(`Hatay Airport: Calculation failed (Mean Radiance: ${airportStats.meanRadiance}).`);
    console.log("C3");
    return;
  }

  // 4. Comparison and Final Answer
  console.log(`Antakya (Mean Radiance): ${antakyaStats.meanRadiance.toFixed(4)} nW/cm²/sr (Pixels: ${antakyaStats.pixelCount})`);
  console.log(`Hatay Airport (Mean Radiance): ${airportStats.meanRadiance.toFixed(4)} nW/cm²/sr (Pixels: ${airportStats.pixelCount})`);

  if (antakyaStats.meanRadiance > airportStats.meanRadiance) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
